declare(strict_types=1);

namespace App\Tests\E2E;

use App\Platform\Settings\ConfigRevision;
use App\Tests\Support\AdminSession;
use App\Tests\Support\Fixtures;
use App\Tests\Support\TestContainer;
use App\Tests\Support\WebClient;
use PHPUnit\Framework\TestCase;

/**
 * Blog UI flows through nginx: Admin (HTMX list, validation, edit with optimistic locking, delete) and
 * Web (end-user list/create/view, permission checks).
 */
final class BlogUiTest extends TestCase
{
    private const UUID = '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}';
    private static bool $revisionBumped = false;

    protected function setUp(): void
    {
        Fixtures::resetLoginThrottle();
        if (!self::$revisionBumped) {
            TestContainer::service(ConfigRevision::class)->bump();
            self::$revisionBumped = true;
        }
    }

    protected function tearDown(): void
    {
        Fixtures::cleanup();
    }

    public function testAdminCrudFlow(): void
    {
        [$web] = AdminSession::login(['business_admin']);
        $r = $web->get('/admin/blog');
        self::assertSame(200, $r->getStatusCode(), substr($web->body(), 0, 500));
        self::assertStringContainsString('Blog', $web->body());

        // validation errors are re-rendered with 422
        $web->get('/admin/blog/create');
        $r = $web->post('/admin/blog/create', []);
        self::assertSame(422, $r->getStatusCode());
        self::assertStringContainsString('field__error', $web->body());
        self::assertStringContainsString('aria-invalid="true"', $web->body());

        $form = $this->form();
        $web->get('/admin/blog/create');
        $r = $web->post('/admin/blog/create', $form);
        self::assertSame(200, $r->getStatusCode(), substr($web->body(), 0, 800));
        self::assertMatchesRegularExpression('#^/admin/blog/' . self::UUID . '$#', $web->url());
        self::assertStringContainsString('Blog created.', $web->body());
        $viewUrl = $web->url();

        // edit: the optimistic version travels in a hidden field; a stale submit is refused
        $web->get($viewUrl . '/edit');
        self::assertStringContainsString('name="version" value="1"', $web->body());
        $edited = $form;
        $edited['title'] = mb_substr('Edited ' . bin2hex(random_bytes(3)), 0, 255);
        $web->post($viewUrl . '/edit', $edited + ['version' => '1']);
        self::assertSame($viewUrl, $web->url());
        $web->get($viewUrl . '/edit');
        $web->post($viewUrl . '/edit', ['version' => '0'] + $form);
        self::assertStringContainsString('modified by someone else', $web->body());

        // HTMX list request returns only the main region and finds the record
        $r = $web->htmx('GET', '/admin/blog?q=' . urlencode((string) $edited['title']));
        self::assertSame(200, $r->getStatusCode());
        self::assertStringStartsWith('<main id="main"', ltrim($web->body()));
        self::assertStringNotContainsString('<html', $web->body());
        self::assertStringContainsString(htmlspecialchars((string) $edited['title'], ENT_QUOTES), $web->body());

        // lifecycle transition (current version read from the page)
        $web->get($viewUrl);
        preg_match('/name="version" value="(\\d+)"/', $web->body(), $mm);
        $web->post($viewUrl . '/status', ['status' => 'active', 'version' => $mm[1] ?? '1']);
        self::assertStringContainsString('Status changed to', $web->body());

        // delete (confirm dialog is client-side; the server enforces the permission)
        $web->get($viewUrl);
        self::assertStringContainsString('data-confirm=', $web->body());
        $web->post($viewUrl . '/delete', []);
        self::assertStringContainsString('Blog deleted.', $web->body());
        self::assertSame(404, $web->get($viewUrl)->getStatusCode());
    }

    public function testAdminForbiddenWithoutPermission(): void
    {
        // auditor inherits "user" (blog.view) but holds no write permission
        [$web] = AdminSession::login(['auditor']);
        self::assertSame(200, $web->get('/admin/blog')->getStatusCode());
        self::assertSame(403, $web->get('/admin/blog/create')->getStatusCode());
        self::assertSame(404, $web->get('/admin/blog/00000000-0000-4000-8000-000000000000')->getStatusCode());
    }

    public function testWebUserFlows(): void
    {
        $manager = Fixtures::user(['business_admin']);
        $web = new WebClient();
        $web->get('/login');
        $web->post('/login', ['login' => $manager['username'], 'password' => $manager['password']]);
        self::assertSame(200, $web->get('/blog')->getStatusCode(), substr($web->body(), 0, 500));
        $web->get('/blog/new');
        $web->post('/blog/new', $this->form());
        self::assertMatchesRegularExpression('#^/blog/' . self::UUID . '$#', $web->url(), substr($web->body(), 0, 800));
        $url = $web->url();

        // a regular user can view but not create
        $user = Fixtures::user(['user']);
        $u = new WebClient();
        $u->get('/login');
        $u->post('/login', ['login' => $user['username'], 'password' => $user['password']]);
        self::assertSame(200, $u->get('/blog')->getStatusCode());
        self::assertSame(200, $u->get($url)->getStatusCode());
        self::assertStringNotContainsString('/edit"', $u->body());
        self::assertSame(403, $u->get('/blog/new')->getStatusCode());
    }

    /** @return array<string,string> */
    private function form(): array
    {
        return [
            'title' => 'Sample title ' . bin2hex(random_bytes(4)),
            'description' => 'Sample description ' . bin2hex(random_bytes(4)),
            'due_on' => '2026-12-31',
        ];
    }
}
